-- CareVoice documentation-service schema, version 1.
-- Conventions: snake_case, UUID primary keys generated by the application (not the database), timestamptz everywhere,
-- every foreign key indexed, personal data stored encrypted (columns ending in _enc).

CREATE TABLE tenants (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE wards (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL REFERENCES tenants (id),
    name        TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX wards_tenant_idx ON wards (tenant_id);

CREATE TABLE residents (
    id                  TEXT PRIMARY KEY,
    tenant_id           TEXT NOT NULL REFERENCES tenants (id),
    ward_id             TEXT NOT NULL REFERENCES wards (id),
    -- AES-256-GCM ciphertext ("<keyId>:<base64(iv|ciphertext|tag)>"), never plaintext.
    display_name_enc    TEXT NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX residents_ward_idx ON residents (ward_id);

CREATE TABLE users (
    username        TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL REFERENCES tenants (id),
    ward_id         TEXT NOT NULL REFERENCES wards (id),
    -- NURSE | WARD_LEAD
    role            TEXT NOT NULL CHECK (role IN ('NURSE', 'WARD_LEAD')),
    password_hash   TEXT NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE transcripts (
    id                  UUID PRIMARY KEY,
    tenant_id           TEXT NOT NULL REFERENCES tenants (id),
    resident_id         TEXT NOT NULL REFERENCES residents (id),
    created_by          TEXT NOT NULL,
    idempotency_key     UUID NOT NULL,
    -- SHA-256 of the canonical request body: same key + different body = 409 Conflict.
    request_hash        TEXT NOT NULL,
    -- Encrypted raw text; set to NULL by the retention job after the retention period (GDPR data minimisation).
    text_enc            TEXT,
    -- The exact response returned on first processing, replayed for retries with the same key.
    response_body       JSONB NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL,
    CONSTRAINT transcripts_idempotency_uq UNIQUE (created_by, idempotency_key)
);
CREATE INDEX transcripts_resident_idx ON transcripts (resident_id);
CREATE INDEX transcripts_retention_idx ON transcripts (created_at) WHERE text_enc IS NOT NULL;

CREATE TABLE observations (
    id                  UUID PRIMARY KEY,
    tenant_id           TEXT NOT NULL REFERENCES tenants (id),
    ward_id             TEXT NOT NULL REFERENCES wards (id),
    resident_id         TEXT NOT NULL REFERENCES residents (id),
    transcript_id       UUID NOT NULL REFERENCES transcripts (id),
    -- BLOOD_PRESSURE | PULSE | BODY_TEMPERATURE; exactly the matching value columns are set (enforced below).
    vital_type          TEXT NOT NULL CHECK (vital_type IN ('BLOOD_PRESSURE', 'PULSE', 'BODY_TEMPERATURE')),
    systolic            INT,
    diastolic           INT,
    pulse_bpm           INT,
    temperature_celsius NUMERIC(3, 1),
    source              TEXT NOT NULL CHECK (source IN ('RULES', 'AI')),
    confidence          NUMERIC(3, 2) NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    status              TEXT NOT NULL CHECK (status IN ('CONFIRMED', 'NEEDS_REVIEW')),
    recorded_at         TIMESTAMPTZ NOT NULL,
    confirmed_by        TEXT,
    confirmed_at        TIMESTAMPTZ,
    -- Optimistic locking: incremented on every update, exposed as the ETag; If-Match must carry it.
    version             INT NOT NULL DEFAULT 0,
    CONSTRAINT observations_values_ck CHECK (
        (vital_type = 'BLOOD_PRESSURE' AND systolic IS NOT NULL AND diastolic IS NOT NULL AND pulse_bpm IS NULL AND temperature_celsius IS NULL)
        OR (vital_type = 'PULSE' AND pulse_bpm IS NOT NULL AND systolic IS NULL AND diastolic IS NULL AND temperature_celsius IS NULL)
        OR (vital_type = 'BODY_TEMPERATURE' AND temperature_celsius IS NOT NULL AND systolic IS NULL AND diastolic IS NULL AND pulse_bpm IS NULL)
    )
);
-- Resident history, newest first, keyset-paginated on (recorded_at, id): serves GET /residents/{id}/observations.
CREATE INDEX observations_resident_recorded_idx ON observations (resident_id, recorded_at DESC, id DESC);
-- Ward-wide queries (QUERY /observations) are always scoped to one ward.
CREATE INDEX observations_ward_recorded_idx ON observations (ward_id, recorded_at DESC, id DESC);
-- The review queue is small compared to the table; a partial index keeps it tiny and fast.
CREATE INDEX observations_needs_review_idx ON observations (ward_id, recorded_at DESC) WHERE status = 'NEEDS_REVIEW';
CREATE INDEX observations_transcript_idx ON observations (transcript_id);

-- Transactional outbox: written in the SAME transaction as the observations, published asynchronously by the relay.
CREATE TABLE outbox (
    id               UUID PRIMARY KEY,
    aggregate_id     UUID NOT NULL,
    event_type       TEXT NOT NULL,
    payload          JSONB NOT NULL,
    -- PENDING -> PUBLISHED, or DEAD after a non-retryable failure / max attempts.
    status           TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'PUBLISHED', 'DEAD')),
    attempts         INT NOT NULL DEFAULT 0,
    next_attempt_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_error       TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at     TIMESTAMPTZ
);
-- The relay's claim query: SELECT ... WHERE status = 'PENDING' AND next_attempt_at <= now() ORDER BY next_attempt_at
-- FOR UPDATE SKIP LOCKED. The partial index only contains rows that still need work.
CREATE INDEX outbox_pending_idx ON outbox (next_attempt_at) WHERE status = 'PENDING';

-- Who did what, for compliance. Never contains personal data: ids and action names only.
CREATE TABLE audit_log (
    id           BIGSERIAL PRIMARY KEY,
    tenant_id    TEXT NOT NULL,
    actor        TEXT NOT NULL,
    action       TEXT NOT NULL,
    entity_type  TEXT NOT NULL,
    entity_id    TEXT NOT NULL,
    occurred_at  TIMESTAMPTZ NOT NULL,
    details      JSONB NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX audit_log_entity_idx ON audit_log (entity_type, entity_id);
CREATE INDEX audit_log_occurred_idx ON audit_log (occurred_at);
